@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--ink:#16312c;--muted:#55716a;--cream:#fffdf5;--leaf:#537d43;--gold:#ffcb66;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#a9dfdf;color:var(--ink);font-family:var(--sans)}button{font:inherit}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#a9dfdf;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.topbar{position:absolute;z-index:2;left:0;right:0;top:0;height:76px;padding:0 40px;display:flex;align-items:center;gap:22px;background:linear-gradient(180deg,rgba(243,252,239,.86),rgba(243,252,239,.63));border-bottom:1px solid rgba(31,68,55,.1);backdrop-filter:blur(12px)}.brand{font:700 19px var(--display);letter-spacing:.045em;display:flex;align-items:center;gap:9px;color:#294a3d}.brand-mark{display:grid;place-items:center;width:30px;height:30px;background:#577b43;color:#f7d579;border-radius:8px;font-size:19px;box-shadow:inset 0 -3px rgba(0,0,0,.14)}.brand-accent{color:#6e934d}.world-chip{margin-left:auto;font:500 10px var(--mono);letter-spacing:.11em;color:#557066;background:rgba(255,255,255,.66);border:1px solid rgba(57,94,75,.14);padding:9px 13px;border-radius:99px;display:flex;align-items:center;gap:8px}.world-chip i,.live-dot{width:7px;height:7px;display:inline-block;background:#84b95d;border-radius:50%;box-shadow:0 0 0 3px rgba(132,185,93,.19)}#seed-label{color:#91a298}.icon-button{width:35px;height:35px;border:1px solid rgba(57,94,75,.15);border-radius:50%;background:rgba(255,255,255,.6);color:#527260;font-size:17px;cursor:pointer}.hud-left{position:absolute;z-index:1;left:40px;top:104px;width:255px}.mini-label,.hotbar-caption,.corner-note{font:500 9px var(--mono);letter-spacing:.16em;color:#426759}.objective{margin-top:11px;display:flex;align-items:center;gap:10px;padding:12px 14px;background:rgba(255,253,245,.87);border:1px solid rgba(44,82,63,.12);border-radius:12px;box-shadow:0 8px 26px rgba(50,87,64,.08);backdrop-filter:blur(8px)}.objective-icon{display:grid;place-items:center;background:#f6e5bb;color:#b48635;border-radius:8px;width:34px;height:34px;font-size:17px}.objective b{display:block;font-size:12px;font-weight:700;color:#284b3e}.objective small{display:block;margin-top:3px;color:#7a9183;font-size:10px}.coords{display:flex;align-items:center;gap:9px;padding:11px 3px;color:#eaf6dc;text-shadow:0 1px 5px rgba(30,67,41,.4);font:500 9px var(--mono);letter-spacing:.07em}.coord-divider{height:11px;width:1px;background:rgba(247,255,234,.5)}#biome{color:#f9f1ce}.crosshair{display:none;position:absolute;pointer-events:none;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.85}.crosshair:before,.crosshair:after{content:'';position:absolute;background:rgba(255,255,255,.9);box-shadow:0 1px 2px #314938}.crosshair:before{width:2px;height:16px;left:8px;top:1px}.crosshair:after{height:2px;width:16px;left:1px;top:8px}.toast{position:absolute;z-index:4;left:50%;top:95px;transform:translate(-50%,-10px);opacity:0;pointer-events:none;transition:.24s;padding:9px 15px;border-radius:99px;background:rgba(29,57,46,.86);color:#f8f2d9;font-size:12px;box-shadow:0 7px 22px #30492a33}.toast.show{opacity:1;transform:translate(-50%,0)}.bottom-ui{position:absolute;z-index:2;bottom:22px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:12px}.help-row{display:flex;align-items:center;gap:7px;white-space:nowrap;color:#eff8dd;text-shadow:0 1px 4px #37553b;font-size:10px}.keycap{padding:4px 6px;border-radius:4px;background:rgba(30,60,45,.4);border:1px solid rgba(245,255,228,.45);font:9px var(--mono);letter-spacing:.03em;color:#fff9dd}.help-sep{opacity:.55;margin:0 2px}.hotbar-wrap{display:flex;flex-direction:column;align-items:center;gap:5px}.hotbar{height:64px;padding:6px;display:flex;gap:5px;border:1px solid rgba(235,247,215,.65);border-radius:11px;background:rgba(31,56,41,.48);box-shadow:0 9px 24px rgba(30,53,37,.2);backdrop-filter:blur(8px)}.slot{position:relative;width:54px;height:50px;border-radius:7px;border:1px solid rgba(241,246,218,.22);background:rgba(246,247,220,.16);display:grid;place-items:center;cursor:pointer;transition:.13s}.slot:hover{background:rgba(255,255,255,.25)}.slot.selected{border:2px solid #ffdc80;background:rgba(255,224,132,.22);box-shadow:0 0 0 2px rgba(42,65,41,.2),0 0 15px rgba(255,222,127,.23);transform:translateY(-3px)}.slot-num{position:absolute;top:3px;left:5px;color:rgba(255,255,236,.68);font:8px var(--mono)}.block-icon{width:26px;height:26px;image-rendering:pixelated;filter:drop-shadow(1px 3px 1px rgba(21,37,25,.3))}.count{position:absolute;bottom:3px;right:5px;color:#fff8d9;font:10px var(--mono);text-shadow:0 1px 2px #30452c}.hotbar-caption{color:#eaf3d9;text-shadow:0 1px 4px #37553b;font-size:8px}.hotbar-caption span{margin-left:8px;opacity:.72}.welcome{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:linear-gradient(90deg,rgba(20,54,49,.16),rgba(20,54,49,.03) 65%);transition:opacity .55s,visibility .55s}.welcome.hidden{opacity:0;visibility:hidden;pointer-events:none}.welcome-card{width:min(440px,calc(100vw - 42px));margin-left:min(38vw,440px);padding:31px 35px 24px;border:1px solid rgba(255,255,255,.75);border-radius:18px;background:rgba(255,253,242,.91);box-shadow:0 26px 90px rgba(39,70,53,.2);backdrop-filter:blur(18px);animation:card-in .6s cubic-bezier(.2,.8,.2,1) both}.eyebrow{display:flex;align-items:center;gap:8px;font:500 9px var(--mono);letter-spacing:.15em;color:#769367}.eyebrow span{width:6px;height:6px;background:#a8c56d;border-radius:50%;box-shadow:0 0 0 4px #a8c56d2c}.welcome h1{font:700 clamp(38px,5vw,54px)/.99 var(--display);letter-spacing:-.055em;color:#294a3d;margin:19px 0 12px}.welcome h1 em{font-style:normal;color:#779b50}.welcome-card p{max-width:330px;margin:0;color:#6b8273;font-size:13px;line-height:1.55}.play-button{margin-top:22px;width:100%;height:48px;display:flex;align-items:center;justify-content:center;gap:17px;border:0;border-radius:9px;background:#547d47;color:#fff9de;font-size:13px;font-weight:700;cursor:pointer;box-shadow:0 5px 0 #3f6338,0 9px 20px #517e4640;transition:transform .15s,background .15s}.play-button:hover{background:#638e51;transform:translateY(-2px)}.play-button:active{transform:translateY(2px);box-shadow:0 2px 0 #3f6338}.play-button span{font-size:17px}.welcome-foot{margin-top:22px;padding-top:15px;border-top:1px solid #e6eadb;color:#9aa68e;font:500 8px var(--mono);letter-spacing:.15em}.welcome-foot span{color:#d5ae5d;margin-right:5px}.welcome-tip{position:absolute;bottom:44px;left:40px;display:flex;align-items:center;gap:10px;color:#f5f8e6;font-size:11px;text-shadow:0 1px 4px #294b39}.welcome-tip b{font:500 8px var(--mono);letter-spacing:.1em;background:rgba(37,71,51,.42);padding:6px 7px;border-radius:4px;color:#ffdd85}.pause-overlay{position:absolute;inset:0;z-index:6;display:none;place-items:center;background:rgba(29,56,46,.45);backdrop-filter:blur(7px)}.pause-overlay.visible{display:grid}.pause-overlay>div{width:min(350px,calc(100vw - 40px));padding:32px;border-radius:16px;background:#fffdf3;text-align:center;box-shadow:0 20px 70px #19372940}.pause-mark{margin:auto;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#edf1df;color:#6b8d50}.pause-overlay h2{font:700 23px var(--display);margin:14px 0 7px}.pause-overlay p{font-size:12px;color:#768879}.corner-note{position:absolute;bottom:28px;right:35px;color:rgba(239,248,221,.8);text-shadow:0 1px 4px #37553b;font-size:8px}.pause-overlay .play-button{margin-top:19px}@keyframes card-in{from{opacity:0;transform:translateY(13px) scale(.98)}to{opacity:1;transform:none}}
@media(max-width:700px){.topbar{height:61px;padding:0 17px}.brand{font-size:16px}.world-chip{font-size:8px;padding:8px 9px}.hud-left{left:16px;top:78px;width:220px}.objective{padding:9px 10px}.objective-icon{width:30px;height:30px}.bottom-ui{bottom:14px}.slot{width:45px;height:46px}.hotbar{height:59px;gap:4px;padding:5px}.help-row{font-size:9px;gap:5px}.welcome-card{margin:0;transform:translateY(-22px);padding:27px 25px 20px}.welcome-tip{left:18px;bottom:20px}.corner-note{display:none}.welcome h1{font-size:43px}.coords{padding-top:8px}.icon-button{width:32px;height:32px}}
@media(max-width:380px){.slot{width:40px}.hotbar{gap:3px}.world-chip{letter-spacing:.04em}.help-row{gap:4px}}

(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const W = 38, H = 38, TW = 64, TH = 32, EH = 22;
  const types = {
    grass: {name:'Grass', top:'#82b85f', side:'#678f4b', dark:'#52763e', icon:['#8fc76a','#6f9f4f','#5a8040']},
    dirt: {name:'Dirt', top:'#b98a59', side:'#916544', dark:'#754d36', icon:['#c69b6b','#9e7149','#805737']},
    stone: {name:'Stone', top:'#a9b5ae', side:'#798980', dark:'#5e7068', icon:['#b8c2bb','#929e96','#727f76']},
    wood: {name:'Wood', top:'#bd8950', side:'#93653b', dark:'#734a2c', icon:['#c9985c','#9c6e40','#79502f']},
    leaves: {name:'Leaves', top:'#78a84f', side:'#527c3e', dark:'#406333', icon:['#91bd63','#699447','#4d7337']},
    flower: {name:'Flower', top:'#e8c96a', side:'#79a752', dark:'#5a813e', icon:['#f0d477','#8fb55c','#6e9148']}
  };
  const inventory = ['grass','dirt','stone','wood','leaves','flower'];
  const count = {grass:24,dirt:12,stone:8,wood:8,leaves:12,flower:5};
  const world = Array.from({length:W},()=>Array(H));
  let seed = 4821, selected = 0, playing = false, paused = false;
  let player = {x:18.5,y:18.5,faceX:1,faceY:0};
  let camera = {x:0,y:0};
  let target = {x:18,y:18};
  let lastTime = 0, toastTimer = 0, soundOn = false;
  const keys = new Set(), mouse = {x:innerWidth/2,y:innerHeight/2,down:false};
  const random = (()=>{let s=seed;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}})();
  function heightAt(x,y){
    const hills = Math.sin(x*.31)*.72 + Math.cos(y*.25)*.66 + Math.sin((x+y)*.19)*.55 + Math.cos((x-y)*.14)*.3;
    return Math.max(0,Math.min(3,Math.floor((hills+1.6)*.79)));
  }
  function makeWorld(){
    for(let x=0;x<W;x++) for(let y=0;y<H;y++){
      const h=heightAt(x,y), r=random();
      const type=r<.11?'stone':'grass';
      world[x][y]={h,type,blocks:[],decor:null};
      if(type==='grass' && r>.28 && r<.34) world[x][y].decor='flower';
      if(type==='grass' && r>.68 && r<.735 && h>0) world[x][y].decor='bush';
      if(type==='grass' && r>.84 && h<3) world[x][y].blocks.push('wood','wood','leaves','leaves');
      if(type==='grass' && r>.795 && r<.815) world[x][y].blocks.push('stone');
    }
    // Keep a generous clearing around the spawn point.
    for(let x=15;x<22;x++) for(let y=15;y<22;y++){
      const t=world[x][y]; t.blocks=[]; t.decor=null; t.type='grass'; t.h=heightAt(x,y);
    }
    world[19][17].blocks=['wood','wood','leaves','leaves'];
    world[16][20].blocks=['stone'];
    world[21][20].decor='flower';
  }
  makeWorld();
  const project=(x,y,z=0)=>({x:(x-y)*TW/2,y:(x+y)*TH/2-z*EH});
  function resize(){const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*d);canvas.height=Math.floor(innerHeight*d);canvas.style.width=innerWidth+'px';canvas.style.height=innerHeight+'px';ctx.setTransform(d,0,0,d,0,0)}
  addEventListener('resize',resize);resize();
  function screenPoint(x,y,z=0){const p=project(x,y,z);return{x:p.x+innerWidth/2-camera.x,y:p.y+innerHeight*.49-camera.y}}
  function setTargetFromMouse(){
    // Invert the isometric projection at the player's ground plane, then bias toward the nearest tile.
    const sx=mouse.x-innerWidth/2+camera.x, sy=mouse.y-innerHeight*.49+camera.y;
    let gx=(sx/(TW/2)+sy/(TH/2))/2, gy=(sy/(TH/2)-sx/(TW/2))/2;
    gx=Math.round(gx);gy=Math.round(gy);
    if(gx<0||gy<0||gx>=W||gy>=H){target={x:-1,y:-1};return}
    target={x:gx,y:gy};
  }
  function color(hex,alpha=1){ctx.globalAlpha=alpha;return hex}
  function poly(points,fill,stroke){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
  function cube(x,y,z,type,scale=1){
    const t=types[type]||types.grass, p=screenPoint(x+.5,y+.5,z), hw=TW*.25*scale, hh=TH*.25*scale, eh=EH*scale;
    // East and south faces
    poly([[p.x,p.y],[p.x+hw,p.y+hh],[p.x+hw,p.y+hh+eh],[p.x,p.y+eh]],t.side);
    poly([[p.x,p.y],[p.x-hw,p.y+hh],[p.x-hw,p.y+hh+eh],[p.x,p.y+eh]],t.dark);
    poly([[p.x,p.y-eh],[p.x+hw,p.y-hh-eh],[p.x,p.y-2*hh-eh],[p.x-hw,p.y-hh-eh]],t.top);
    // Tiny, restrained pixel flecks make block faces read as textured.
    if(type==='stone'||type==='dirt'||type==='grass'){
      ctx.fillStyle=type==='stone'?'rgba(255,255,255,.17)':'rgba(255,255,255,.12)';
      ctx.fillRect(p.x-5*scale,p.y-eh-3*scale,3*scale,2*scale);
    }
  }
  function groundTile(x,y,t){
    const p=screenPoint(x+.5,y+.5,t.h), hw=TW/2,hh=TH/2;
    // Exposed edges descend to the neighboring terrain height.
    const south=world[x][Math.min(H-1,y+1)].h, east=world[Math.min(W-1,x+1)][y].h;
    if(t.h>south) poly([[p.x,p.y],[p.x+hw,p.y+hh],[p.x+hw,p.y+hh+(t.h-south)*EH],[p.x,p.y+(t.h-south)*EH]],types[t.type].side);
    if(t.h>east) poly([[p.x,p.y],[p.x-hw,p.y+hh],[p.x-hw,p.y+hh+(t.h-east)*EH],[p.x,p.y+(t.h-east)*EH]],types[t.type].dark);
    poly([[p.x,p.y-TH/2],[p.x+hw,p.y],[p.x,p.y+hh],[p.x-hw,p.y]],types[t.type].top);
  }

